import {CommandIconButton, GlobalCommands} from '@github-ui/ui-commands'
import {useClickAnalytics} from '@github-ui/use-analytics'
import {useNavigate} from '@github-ui/use-navigate'
import {XIcon} from '@primer/octicons-react'
import {Button, Popover} from '@primer/react'
import React from 'react'

import type {TabPopoverData} from '../types'
import styles from './NavigationTabPopover.module.css'

export interface NavigationTabPopoverProps {
  id: string
  popoverData: TabPopoverData
  onDismiss: () => void
}

/**
 * A popover component that displays on a navigation tab to provide contextual
 * messaging and a call-to-action.
 */
export function NavigationTabPopover({id, popoverData, onDismiss}: NavigationTabPopoverProps) {
  const {sendClickAnalyticsEvent} = useClickAnalytics()
  const navigate = useNavigate()

  const handleCtaClick = (e: React.MouseEvent) => {
    e.stopPropagation()
    e.preventDefault()

    if (popoverData.analytics) {
      sendClickAnalyticsEvent({
        label: popoverData.analytics.label,
        target_url: popoverData.analytics.target_url,
        view: popoverData.analytics.view,
      })
    }
    onDismiss()

    navigate(popoverData.cta.href)
  }

  return (
    <>
      <GlobalCommands commands={{'github:cancel': onDismiss}} />
      <Popover open className={styles.PopoverContainer} popover="manual" caret="top-left" id={id}>
        <Popover.Content onClickOutside={() => onDismiss()} className={styles.PopoverContent}>
          <CommandIconButton
            aria-label="Dismiss"
            commandId={'github:cancel'}
            icon={XIcon}
            variant="invisible"
            className={styles.CloseButton}
          />
          <h4 className={styles.PopoverHeader}>{popoverData.header}</h4>
          <p className={styles.PopoverMessage}>{popoverData.message}</p>
          <Button onClick={handleCtaClick}>{popoverData.cta.label}</Button>
        </Popover.Content>
      </Popover>
    </>
  )
}
